with valid_suppliers as (select *, case when country = 'SG' then 1 else 0 end as is_sg from suppliers where supplier_name like 'Eu%' and rating > 1.8), summary as (select case when is_sg >= 65 then 'high' when is_sg >= 24 then 'mid' else 'low' end as is_sg_bucket, avg(rating) as avg_rating from valid_suppliers group by case when is_sg >= 65 then 'high' when is_sg >= 24 then 'mid' else 'low' end) select is_sg_bucket, avg_rating from summary where avg_rating < 2.8 order by is_sg_bucket, 2 desc limit 10
